# Generated by rex-statusline init zsh.
[[ -o interactive && -n ${REX_SESSION:-} && -n ${REX_BLOCK:-} ]] || return 0
[[ -z ${SSH_CONNECTION:-} && -z ${SSH_TTY:-} ]] || return 0
[[ ${_bsp_initialized:-} == zsh ]] && return 0
autoload -Uz add-zsh-hook
zmodload zsh/datetime
zmodload zsh/parameter
typeset -g _bsp_executable=@EXECUTABLE@
typeset -gF _bsp_started=0
typeset -gi _bsp_duration_ms=0

_bsp_preexec() {
  _bsp_started=$EPOCHREALTIME
}

_bsp_precmd() {
  local last_status=$?
  emulate -L zsh
  [[ -z ${SSH_CONNECTION:-} && -z ${SSH_TTY:-} ]] || return 0
  if (( _bsp_started > 0 )); then
    (( _bsp_duration_ms = (EPOCHREALTIME - _bsp_started) * 1000 ))
    _bsp_started=0
  fi
  command "$_bsp_executable" publish --source local --owner "$$" \
    --cwd "$PWD" --jobs "${#jobstates}" --exit-code "$last_status" \
    --duration-ms "$_bsp_duration_ms" >/dev/null 2>&1
  return 0
}
add-zsh-hook preexec _bsp_preexec
add-zsh-hook precmd _bsp_precmd
typeset -g _bsp_initialized=zsh
